    // Compute which of the eight equally‐spaced points to return.
    let idx: u8 = state.seed % 8;
    // Cast to float and scale by 1/8:
    let res: f32 = (idx as f32) * (1.0f32 / 8.0f32);

    // Verification obligations:
    assert(idx <= 7);                   // idx ∈ 0..=7
    assert(res >= 0.0f32);              // non‐negative
    assert(res < 1.0f32);               // strictly below 1.0

